namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace RecipeHub.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Category is required.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please provide at least one ingredient.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please provide at least one step.")]
    public string Steps { get; set; } = string.Empty;

    public string Description { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Dictionary<int, List<int>> _ratings = new();

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple yet delicious pizza with fresh basil and mozzarella.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = ["Preheat oven to 475°F.", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly.", "Tear mozzarella and distribute over sauce.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
                AverageRating = 4.5, RatingCount = 12
            },
            new Recipe
            {
                Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a creamy, spiced tomato sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato puree", "Heavy cream", "Onion", "Garlic", "Ginger"],
                Steps = ["Marinate chicken in yogurt and spices for 2 hours.", "Grill or pan-fry chicken until charred.", "Sauté onions, garlic, and ginger.", "Add tomato puree and spices, simmer 15 minutes.", "Stir in cream and add chicken.", "Serve with basmati rice or naan."],
                AverageRating = 4.8, RatingCount = 24
            },
            new Recipe
            {
                Id = 3, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in crispy taco shells with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 minutes.", "Warm taco shells in the oven.", "Fill shells with seasoned beef.", "Top with lettuce, tomato, cheese, sour cream, and salsa."],
                AverageRating = 4.2, RatingCount = 18
            },
            new Recipe
            {
                Id = 4, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Classic Roman pasta with eggs, cheese, and pancetta.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
                Steps = ["Cook spaghetti in salted water until al dente.", "Crisp pancetta in a skillet.", "Whisk eggs with grated Pecorino and pepper.", "Toss hot pasta with pancetta.", "Remove from heat and stir in egg mixture quickly.", "Serve immediately with extra cheese."],
                AverageRating = 4.6, RatingCount = 15
            },
            new Recipe
            {
                Id = 5, Title = "Pad Thai", Category = "Thai",
                Description = "Stir-fried rice noodles with shrimp, peanuts, and tangy sauce.",
                Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Peanuts", "Lime", "Fish sauce", "Tamarind paste", "Sugar"],
                Steps = ["Soak rice noodles in warm water for 30 minutes.", "Make sauce: mix tamarind paste, fish sauce, and sugar.", "Stir-fry shrimp until pink, set aside.", "Scramble eggs in the wok.", "Add noodles and sauce, toss until coated.", "Add shrimp, bean sprouts, and peanuts. Serve with lime."],
                AverageRating = 4.4, RatingCount = 20
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and creamy avocado dip with lime and cilantro.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = ["Halve avocados and remove pits.", "Mash avocado to desired consistency.", "Stir in diced onion, jalapeño, and tomato.", "Add lime juice, cilantro, and salt.", "Serve immediately with tortilla chips."],
                AverageRating = 4.7, RatingCount = 30
            },
            new Recipe
            {
                Id = 7, Title = "Green Curry", Category = "Thai",
                Description = "Aromatic coconut curry with vegetables and Thai basil.",
                Ingredients = ["Green curry paste", "Coconut milk", "Chicken or tofu", "Bamboo shoots", "Thai basil", "Fish sauce", "Sugar", "Bell pepper"],
                Steps = ["Heat coconut cream in a pot until oil separates.", "Fry curry paste for 2 minutes until fragrant.", "Add protein and cook through.", "Pour in coconut milk, bamboo shoots, and bell pepper.", "Season with fish sauce and sugar.", "Garnish with Thai basil and serve over jasmine rice."],
                AverageRating = 4.3, RatingCount = 11
            },
            new Recipe
            {
                Id = 8, Title = "Butter Chicken", Category = "Indian",
                Description = "Rich and creamy tomato-based chicken curry.",
                Ingredients = ["Chicken thighs", "Butter", "Tomato sauce", "Heavy cream", "Garam masala", "Kashmiri chili", "Garlic", "Ginger", "Fenugreek leaves"],
                Steps = ["Marinate chicken in yogurt and spices.", "Grill or bake chicken until cooked.", "Melt butter, sauté garlic and ginger.", "Add tomato sauce and spices, simmer 20 minutes.", "Stir in cream and fenugreek leaves.", "Add chicken and simmer 10 more minutes."],
                AverageRating = 4.9, RatingCount = 28
            }
        ];
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
        {
            _ratings[recipeId] = [];
        }
        _ratings[recipeId].Add(stars);

        var totalRatings = recipe.RatingCount + _ratings[recipeId].Count;
        var totalSum = (recipe.AverageRating * recipe.RatingCount) + _ratings[recipeId].Sum();
        recipe.AverageRating = Math.Round(totalSum / totalRatings, 1);
        recipe.RatingCount = totalRatings;
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Description = submission.Description,
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

