@page "/category/{CategoryName}"
@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>
<p><a href="/">← Back to Categories</a></p>

@if (recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="card-text">@recipe.Description</p>
                        <div class="d-flex justify-content-between align-items-center">
                            <span class="text-warning">
                                @for (int i = 1; i <= 5; i++)
                                {
                                    @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                                }
                                <small class="text-muted">(@recipe.AverageRating / 5, @recipe.RatingCount ratings)</small>
                            </span>
                            <a href="recipe/@recipe.Id" class="btn btn-sm btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    private IReadOnlyList<RecipeHub.Models.Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/">← Back to Home</a>
}
else
{
    <p><a href="category/@recipe.Category">← Back to @recipe.Category Recipes</a></p>

    <h1>@recipe.Title</h1>
    <p class="lead text-muted">@recipe.Description</p>

    <div class="row">
        <div class="col-md-6">
            <h3>🧾 Ingredients</h3>
            <ul class="list-group mb-4">
                @foreach (var ingredient in recipe.Ingredients)
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>
        </div>
        <div class="col-md-6">
            <h3>👩‍🍳 Steps</h3>
            <ol class="list-group list-group-numbered mb-4">
                @foreach (var step in recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <div class="card mt-4">
        <div class="card-body">
            <h4>Rate this Recipe</h4>
            <StarRating RecipeId="recipe.Id" CurrentRating="recipe.AverageRating" RatingCount="recipe.RatingCount" />
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }
    private RecipeHub.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer
@inject RecipeHub.Services.RecipeService RecipeService

<div class="d-inline-block">
    <span class="star-rating">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= (hoveredStar > 0 ? hoveredStar : selectedStar) ? "filled" : "")"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => hoveredStar = star"
                  @onmouseout="() => hoveredStar = 0"
                  style="cursor: pointer; font-size: 1.8rem;">
                @(star <= (hoveredStar > 0 ? hoveredStar : selectedStar) ? "★" : "☆")
            </span>
        }
    </span>

    @if (submitted)
    {
        <span class="text-success ms-3">✓ Thanks for rating!</span>
    }

    <div class="text-muted mt-1">
        <small>Average: @CurrentRating / 5 (@RatingCount ratings)</small>
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int selectedStar;
    private int hoveredStar;
    private bool submitted;

    private void Rate(int stars)
    {
        selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeHub.Services.RecipeService RecipeService
@using RecipeHub.Models

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (successMessage is not null)
{
    <div class="alert alert-success">@successMessage</div>
}

<EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="submission.Title" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => submission.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
            <option value="">-- Select a category --</option>
            @foreach (var cat in RecipeService.GetCategories())
            {
                <option value="@cat">@cat</option>
            }
            <option value="American">American</option>
            <option value="French">French</option>
            <option value="Japanese">Japanese</option>
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => submission.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="description" class="form-label">Short Description</label>
        <InputTextArea id="description" class="form-control" @bind-Value="submission.Description" rows="2" placeholder="A brief description of your recipe" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" @bind-Value="submission.Ingredients" rows="6" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        <ValidationMessage For="() => submission.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" @bind-Value="submission.Steps" rows="6" placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
        <ValidationMessage For="() => submission.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
</EditForm>

@code {
    private RecipeSubmission submission = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(submission);
        successMessage = $"'{submission.Title}' has been submitted successfully!";
        submission = new();
    }
}

